import * as fs from "node:fs/promises";
import * as path from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  cleanupTempDir,
  createTempDir,
  initGitRepo,
  kspecWithStatus,
  testUlid,
} from "./helpers/cli";

// AC: @alignment-warnings ac-1

describe("validate alignment: no-task spec warning policy", () => {
  let tmpDir: string;

  beforeEach(async () => {
    tmpDir = await createTempDir("kspec-align-no-task-");
    initGitRepo(tmpDir);
  });

  afterEach(async () => {
    if (tmpDir) {
      await cleanupTempDir(tmpDir);
    }
  });

  async function writeProject(
    specStatus: string,
    includeTasks: boolean,
    taskStatus = "pending",
  ): Promise<void> {
    const specUlid = testUlid("SPEC01");
    const taskUlid = testUlid("TASK01");

    await fs.writeFile(
      path.join(tmpDir, "kynetic.yaml"),
      `kynetic: "1.0"
project:
