    await fs.mkdir(specDir, { recursive: true });

    const specUlid = testUlid("SPEC01");
    const taskUlid = testUlid("TASK01");

    await fs.writeFile(
      path.join(rootDir, "kynetic.yaml"),
      `kynetic: "1.0"
project:
  name: validate-mode-test
  version: 0.1.0
includes:
  - "spec/module.yaml"
tasks:
  - "spec/project.tasks.yaml"
`,
    );

